#include <stdio.h>

int main(void)
{
    int a = 0, b = 0;
    sscanf("032 032", "%i %d", &a, &b);
    printf("%d %d\n", a, b);
    return 0;
}

#include <stdio.h>

int main(void)
{
    int roll = 0;
    char grade = '?';
    int assigned = sscanf("42\nA", "%d %c", &roll, &grade);
    printf("%d %d %c\n", assigned, roll, grade);
    return 0;
}

